MOD = 1000000007

def mod_pow(base, exponent, modulus):
    result = 1
    while exponent > 0:
        if exponent % 2 == 1:
            result = (result * base) % modulus
        exponent = exponent >> 1
        base = (base * base) % modulus
    return result

def mod_inv(a, modulus):
    return mod_pow(a, modulus - 2, modulus)

def mod_perm(matrix, modulus):
    n = len(matrix)
    result = 1
    for i in range(n):
        for j in range(i + 1, n):
            while matrix[i][j] != 0:
                ratio = matrix[i][j] // matrix[i][i]
                for k in range(i, n):
                    matrix[i + 1][k] = (matrix[i + 1][k] - ratio * matrix[i][k]) % modulus
                for k in range(i, n):
                    matrix[i][k], matrix[i + 1][k] = matrix[i + 1][k], matrix[i][k]
                result = (result * matrix[i][i]) % modulus
                n -= 1
    return result

def count_seatings(N, desks):
    max_desk = 2 * N
    matrix = [[0] * (max_desk + 1) for _ in range(max_desk + 1)]

    for current, desired in desks:
        matrix[current][desired] = 1

    return mod_perm(matrix, MOD)

